(149997, 7744, 327, '<td valign="top">Wow fantastic capture!!!!!!! Justine</td>', 'Wow fantastic capture!!!!!!! Justine', '2002-11-04 16:14:00.000000', NULL, 1),
(149998, 7744, 2716, '<td valign="top">Cool.  The cat looks completely pitch black.  is this a cut out?  Great job.  Just being picky: I think I would like to have seen more cropping.  8 Jacko.</td>', 'Cool.  The cat looks completely pitch black.  is this a cut out?  Great job.  Just being picky: I think I would like to have seen more cropping.  8 Jacko.', '2002-11-04 20:42:00.000000', NULL, 1),
