(150213, 7761, 2716, '<td valign="top">Hey, a fellow mirror entry.  Good job.  Jacko</td>', 'Hey, a fellow mirror entry.  Good job.  Jacko', '2002-11-06 17:16:00.000000', NULL, 1),
(150214, 7761, 4005, '<td valign="top">The same idea, I had too! But didn''t find a mirror I wanted to destroy for that, so I didn''t submitt anything... ;o) However, now I know how it would have looked like.. I wish you lot of luck for the challenge  (despite the broken mirror), 8 - KAOS.</td>', 'The same idea, I had too! But didn''t find a mirror I wanted to destroy for that, so I didn''t submitt anything... ;o) However, now I know how it would have looked like.. I wish you lot of luck for the challenge  (despite the broken mirror), 8 - KAOS.', '2002-11-07 10:08:00.000000', NULL, 1),
(150215, 7761, 772, '<td valign="top">very nice shot.. i didn''t have to guess at the supersition on this one... good work :) - setzler</td>', 'very nice shot.. i didn''t have to guess at the supersition on this one... good work :) - setzler', '2002-11-07 16:27:00.000000', NULL, 1),
(150216, 7761, 1707, '<td valign="top">I like the simple colors</td>', 'I like the simple colors', '2002-11-09 06:48:00.000000', NULL, 1),
(150217, 7761, 4648, '<td valign="top">There were quite a few broken mirrors and each one was unique in itself.  This one is unique because all it is is a broken mirror - no reflection of anyone or anything.  I like the simplicity and the sharpness of the focus and picture.  A real nice 8</td>', 'There were quite a few broken mirrors and each one was unique in itself.  This one is unique because all it is is a broken mirror - no reflection of anyone or anything.  I like the simplicity and the sharpness of the focus and picture.  A real nice 8', '2002-11-09 15:20:00.000000', NULL, 1),
(150218, 7761, 4455, '<td valign="top">wonderful dramatic photo-anz</td>', 'wonderful dramatic photo-anz', '2002-11-10 06:09:00.000000', NULL, 1),
(150219, 7761, 2553, '<td valign="top">I like the concept, but would have liked to have seen a face reflected in the pieces. lhall</td>', 'I like the concept, but would have liked to have seen a face reflected in the pieces. lhall', '2002-11-10 20:42:00.000000', NULL, 1),
(150220, 7762, 4493, '<td valign="top">Reflection in the window is sort of distracting. Perhaps a tighter crop on the subject would help too.</td>', 'Reflection in the window is sort of distracting. Perhaps a tighter crop on the subject would help too.', '2002-11-04 09:46:00.000000', NULL, 1),
(150221, 7762, 4758, '<td valign="top">pity about the reflections, they kind of takes your interest away from the subject.</td>', 'pity about the reflections, they kind of takes your interest away from the subject.', '2002-11-04 11:55:00.000000', NULL, 1),
(150222, 7762, 4472, '<td valign="top">Very distracting window reflections</td>', 'Very distracting window reflections', '2002-11-04 12:20:00.000000', NULL, 1),
(150223, 7762, 1569, '<td valign="top">Way too many reflections making this a confusing shot.</td>', 'Way too many reflections making this a confusing shot.', '2002-11-04 19:30:00.000000', NULL, 1),
