INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(150226, 7762, 3102, '<td valign="top">I''m afraid that the strong reflections in the mirror are WAY to overpowering here, not to mention that I''m not sure about the message you''re trying to convey.  Sorry...</td>', 'I''m afraid that the strong reflections in the mirror are WAY to overpowering here, not to mention that I''m not sure about the message you''re trying to convey.  Sorry...', '2002-11-05 16:22:00.000000', NULL, 1),
(150227, 7762, 3080, '<td valign="top">I am not quite sure I get this.  Is there suposed to be a connection between the reflection and the statue? If not, the reflections are really quite distracting, making the photo quite busy and cluttered.  I am not assuming anything though, as I understand that I''m not a superstition expert.  I do think that it''s busy, the lighting it too dark to get much detail, and focus is soft most likely due to the fact that it''s shot through glass.  I think this could be better. Good luck in the challenge. ~Hbunch7187~</td>', 'I am not quite sure I get this.  Is there suposed to be a connection between the reflection and the statue? If not, the reflections are really quite distracting, making the photo quite busy and cluttered.  I am not assuming anything though, as I understand that I''m not a superstition expert.  I do think that it''s busy, the lighting it too dark to get much detail, and focus is soft most likely due to the fact that it''s shot through glass.  I think this could be better. Good luck in the challenge. ~Hbunch7187~', '2002-11-09 19:31:00.000000', NULL, 1),
(150228, 7762, 2221, '<td valign="top">Interesting how the store with the symbols of the US on the other side of the street reflects in the window of a shop with christian symbols. -stephan</td>', 'Interesting how the store with the symbols of the US on the other side of the street reflects in the window of a shop with christian symbols. -stephan', '2002-11-10 14:45:00.000000', NULL, 1),
(150229, 7762, 4615, '<td valign="top">How obvious does one have to be?   When the American flag is reflected directly on to the Madonna''s heart I think that''s a pretty good indication that thats the POINT of the picture, not a "distraction".   I didn''t know how it would turn out until I relooked at the picture afterwards, when I saw how the objects both in and out of the window were positioned I knew that this was one of those serendipetus photographic moments and there was no choice but to submit it this week, even if the focus and light were less than perfect.<br/>I recommend that most of the commentators below visit a few art gallerys at some point.</td>', 'How obvious does one have to be?   When the American flag is reflected directly on to the Madonna''s heart I think that''s a pretty good indication that thats the POINT of the picture, not a "distraction".   I didn''t know how it would turn out until I relooked at the picture afterwards, when I saw how the objects both in and out of the window were positioned I knew that this was one of those serendipetus photographic moments and there was no choice but to submit it this week, even if the focus and light were less than perfect.I recommend that most of the commentators below visit a few art gallerys at some point.', '2002-11-11 07:55:00.000000', NULL, 0),
(150230, 7763, 888, '<td valign="top">I think this pic relies on teh title too much to get across its idea.</td>', 'I think this pic relies on teh title too much to get across its idea.', '2002-11-04 06:12:00.000000', NULL, 1),
(150231, 7763, 4493, '<td valign="top">Fine candid shot using the camera flash. Typical shadows and DOF.</td>', 'Fine candid shot using the camera flash. Typical shadows and DOF.', '2002-11-04 11:01:00.000000', NULL, 1),
(150232, 7763, 3317, '<td valign="top">wow, far out. i know folks go to extreme lengths to set up these dpchallenge shots, but it''s not often that they actually leave the solar system. nice job.</td>', 'wow, far out. i know folks go to extreme lengths to set up these dpchallenge shots, but it''s not often that they actually leave the solar system. nice job.', '2002-11-04 12:09:00.000000', NULL, 1),
