(150234, 7763, 327, '<td valign="top">Very cool shot. LOL Fun work. -Good luck-<br/>Justine.</td>', 'Very cool shot. LOL Fun work. -Good luck-Justine.', '2002-11-04 18:32:00.000000', NULL, 1),
(150235, 7763, 4815, '<td valign="top">Man I laughed my innards out on this one. Hilarious!</td>', 'Man I laughed my innards out on this one. Hilarious!', '2002-11-04 19:56:00.000000', NULL, 1),
