(150261, 7764, 205, '<td valign="top">no way dude thats such a rad feeling.</td>', 'no way dude thats such a rad feeling.', '2002-11-06 21:05:00.000000', NULL, 1),
(150262, 7764, 3540, '<td valign="top">This photo is too dark.  I''m not really sold on the composition of it either.   That may be because I had a similar idea (great minds think alike :)  ).  I think the portrayal of this could''ve been better or at least on this photo, a little more exposure would be a substantial improvement. - Inspzil<br/></td>', 'This photo is too dark.  I''m not really sold on the composition of it either.   That may be because I had a similar idea (great minds think alike :)  ).  I think the portrayal of this could''ve been better or at least on this photo, a little more exposure would be a substantial improvement. - Inspzil', '2002-11-07 08:48:00.000000', NULL, 1),
(150263, 7764, 3532, '<td valign="top">Good idea, but the picture is too dark.  I can hardly see the pop rocks.  Would''ve been more fun to actually see someon eating/drinking them.</td>', 'Good idea, but the picture is too dark.  I can hardly see the pop rocks.  Would''ve been more fun to actually see someon eating/drinking them.', '2002-11-07 19:16:00.000000', NULL, 1),
