(150696, 7798, 5070, '<td valign="top">Catsup would have looked more realistic than kool-aid (lol)</td>', 'Catsup would have looked more realistic than kool-aid (lol)', '2002-11-09 23:14:00.000000', NULL, 1),
(150697, 7798, 4455, '<td valign="top">nice composition,well done-anz</td>', 'nice composition,well done-anz', '2002-11-10 13:17:00.000000', NULL, 1),
(150698, 7798, 4186, '<td valign="top">you do know that in most tarot readings the death card only means change, and not literally death, right? ah well, at least it''s a knife and not a sniper rifle. well done shot.</td>', 'you do know that in most tarot readings the death card only means change, and not literally death, right? ah well, at least it''s a knife and not a sniper rifle. well done shot.', '2002-11-10 18:50:00.000000', NULL, 1),
(150699, 7798, 2553, '<td valign="top">Kind of creepy feeling! lhall</td>', 'Kind of creepy feeling! lhall', '2002-11-10 20:43:00.000000', NULL, 1),
(150700, 7798, 2009, '<td valign="top">Wrong card. Should be hanged man.  like the colors and basic composition but the surup is too thin.</td>', 'Wrong card. Should be hanged man.  like the colors and basic composition but the surup is too thin.', '2002-11-10 20:48:00.000000', NULL, 1),
(150701, 7799, 3900, '<td valign="top">Nice pic, pretty woman.  It looks a bit skewed though ...squeezed from the sides.  You need to keep the proportion when resizing.</td>', 'Nice pic, pretty woman.  It looks a bit skewed though ...squeezed from the sides.  You need to keep the proportion when resizing.', '2002-11-04 02:54:00.000000', NULL, 1),
(150702, 7799, 4493, '<td valign="top">Image should have been cropped to 480x640 instead of resized. There is distortion as a result. Good candid shot though.</td>', 'Image should have been cropped to 480x640 instead of resized. There is distortion as a result. Good candid shot though.', '2002-11-04 10:14:00.000000', NULL, 1),
(150703, 7799, 2535, '<td valign="top">ya so?</td>', 'ya so?', '2002-11-04 12:30:00.000000', NULL, 1),
(150704, 7799, 2792, '<td valign="top">Personally, I really don''t think Cat Woman is a superstition.  The quality of the photo could be better also.  Sorry!  =-(</td>', 'Personally, I really don''t think Cat Woman is a superstition.  The quality of the photo could be better also.  Sorry!  =-(', '2002-11-04 15:10:00.000000', NULL, 1),
(150705, 7799, 772, '<td valign="top">I think this image is suffering from some resizing distortion... her head looks ''squeezed'' :) - setzler</td>', 'I think this image is suffering from some resizing distortion... her head looks ''squeezed'' :) - setzler', '2002-11-04 15:37:00.000000', NULL, 1),
(150706, 7799, 327, '<td valign="top">Julie Newmar? LOL great fun, pretty lady. Maybe a bit fuzzy but I like it. :O) Justine.</td>', 'Julie Newmar? LOL great fun, pretty lady. Maybe a bit fuzzy but I like it. :O) Justine.', '2002-11-04 16:09:00.000000', NULL, 1),
