(150802, 7809, 4005, '<td valign="top">One more I don''t know - wating for explaination and wishing good luck for the challenge... 7 - KAOS<br/>p.s.: Seems to be quite expensive cake?!?</td>', 'One more I don''t know - wating for explaination and wishing good luck for the challenge... 7 - KAOSp.s.: Seems to be quite expensive cake?!?', '2002-11-04 07:38:00.000000', NULL, 1),
(150803, 7809, 4829, '<td valign="top">Nice display and setup...Those cookies look worth the $250! Or maybe I am just hungry....nice creativity...-8-</td>', 'Nice display and setup...Those cookies look worth the $250! Or maybe I am just hungry....nice creativity...-8-', '2002-11-04 09:57:00.000000', NULL, 1),
(150804, 7809, 4493, '<td valign="top">I like the texture of the table cloth. It draws the eye throughout the whole shot. Good lighting and DOF. Nit-picking, but a cloth napkin would have kept the soft look of the table cloth. Composition is good.</td>', 'I like the texture of the table cloth. It draws the eye throughout the whole shot. Good lighting and DOF. Nit-picking, but a cloth napkin would have kept the soft look of the table cloth. Composition is good.', '2002-11-04 11:03:00.000000', NULL, 1),
(150805, 7809, 3102, '<td valign="top">I hadn''t heard this one before, but after seeing a couple similar shots I had to head to Google to learn more!  Very amusing story, nice shot :)</td>', 'I hadn''t heard this one before, but after seeing a couple similar shots I had to head to Google to learn more!  Very amusing story, nice shot :)', '2002-11-04 11:32:00.000000', NULL, 1),
(150806, 7809, 4758, '<td valign="top">What is it about this Neiman Marcus ? I''ve seen this theme before in this weeks challenge. Is it some sort of legend about a guy who gets something in his cookie and then suits the company? <br/><br/>It''s a nice picture, but I''m afraid that the message gets losts amongst us non americans...</td>', 'What is it about this Neiman Marcus ? I''ve seen this theme before in this weeks challenge. Is it some sort of legend about a guy who gets something in his cookie and then suits the company? It''s a nice picture, but I''m afraid that the message gets losts amongst us non americans...', '2002-11-04 11:58:00.000000', NULL, 1),
(150807, 7809, 4735, '<td valign="top">lol, im sorry i don''t get it but cool photo</td>', 'lol, im sorry i don''t get it but cool photo', '2002-11-04 17:44:00.000000', NULL, 1),
