(150835, 7810, 1003, '<td valign="top">Been there and done that.....</td>', 'Been there and done that.....', '2002-11-05 16:10:00.000000', NULL, 1),
(150836, 7810, 3102, '<td valign="top">Ok, I had a hard time deciding this week, but I''m giving you my weekly "Alan''s Surefire Pick of the Week Award!"  I have correctly picked the winner the last two weeks, so let''s see if I can make it three in a row!  You''re my only 10 this week.  Nice job -- I love the facial expression!</td>', 'Ok, I had a hard time deciding this week, but I''m giving you my weekly "Alan''s Surefire Pick of the Week Award!"  I have correctly picked the winner the last two weeks, so let''s see if I can make it three in a row!  You''re my only 10 this week.  Nice job -- I love the facial expression!', '2002-11-05 16:11:00.000000', NULL, 1),
(150837, 7810, 4210, '<td valign="top">I like the arrangement of shards in this photo, but I really really wish it reflected a more neutral expression. It seems kinda cheesy this way.</td>', 'I like the arrangement of shards in this photo, but I really really wish it reflected a more neutral expression. It seems kinda cheesy this way.', '2002-11-05 21:05:00.000000', NULL, 1),
(150838, 7810, 3540, '<td valign="top">From the look on the guy''s face, I think you smashed the mirror with his new digital camera.  Well done - Inspzil</td>', 'From the look on the guy''s face, I think you smashed the mirror with his new digital camera.  Well done - Inspzil', '2002-11-05 23:12:00.000000', NULL, 1),
(150839, 7810, 3290, '<td valign="top">This was the first idea I had. You''ve executed it well, and the B&amp;W sets it off. Well done. (Nice expression, too)</td>', 'This was the first idea I had. You''ve executed it well, and the B&W sets it off. Well done. (Nice expression, too)', '2002-11-06 05:03:00.000000', NULL, 1),
(150840, 7810, 4266, '<td valign="top">Nice.</td>', 'Nice.', '2002-11-06 11:08:00.000000', NULL, 1),
(150841, 7810, 5070, '<td valign="top">Well executed and broad in appeal</td>', 'Well executed and broad in appeal', '2002-11-06 19:22:00.000000', NULL, 1),
(150842, 7810, 4293, '<td valign="top">Out of all the broken mirror shots this week, this is the only one that I like.  I appreciate the way that you thought out what was going to be reflecting and how and what a great expression.  It makes me think of an Alfred Hitchcock movie for some reason.</td>', 'Out of all the broken mirror shots this week, this is the only one that I like.  I appreciate the way that you thought out what was going to be reflecting and how and what a great expression.  It makes me think of an Alfred Hitchcock movie for some reason.', '2002-11-06 23:46:00.000000', NULL, 1),
(150843, 7810, 2706, '<td valign="top">that''s freaky but really neat. the black and white makes the picture.</td>', 'that''s freaky but really neat. the black and white makes the picture.', '2002-11-07 20:02:00.000000', NULL, 1),
(150844, 7810, 772, '<td valign="top">excellent shot... I love the stark contrasts created by the broken mirror... great shot :) = 10 - setzler</td>', 'excellent shot... I love the stark contrasts created by the broken mirror... great shot :) = 10 - setzler', '2002-11-08 06:01:00.000000', NULL, 1),
