(150847, 7810, 4517, '<td valign="top">My favorite this week 10. marbo</td>', 'My favorite this week 10. marbo', '2002-11-09 12:58:00.000000', NULL, 1),
(150848, 7810, 3669, '<td valign="top">Very nice.  The shards of glass are displayed nicey and it is in good focus.  The only thing that I don''t like about it is the slight graininess of the photo.  It meets the challenge well.  9</td>', 'Very nice.  The shards of glass are displayed nicey and it is in good focus.  The only thing that I don''t like about it is the slight graininess of the photo.  It meets the challenge well.  9', '2002-11-10 15:13:00.000000', NULL, 1),
