(150850, 7810, 527, '<td valign="top">I would have given this a higher score if the expression didn''t look so staged. The composition is pretty good.<br/><br/>T</td>', 'I would have given this a higher score if the expression didn''t look so staged. The composition is pretty good.T', '2002-11-10 23:04:00.000000', NULL, 1),
(150851, 7810, 3102, '<td valign="top">Dang, my "Surefire Award" streak has ended... but I still think this was tops this week :)</td>', 'Dang, my "Surefire Award" streak has ended... but I still think this was tops this week :)', '2002-11-11 09:16:00.000000', NULL, 0),
(150852, 7810, 2716, '<td valign="top">Aaaahhhhhhhhh Geeeeee!  Fourth place.  ha ha!  Thanks for all the wonderfull comments.  I really enjoyed working on this shot.</td>', 'Aaaahhhhhhhhh Geeeeee!  Fourth place.  ha ha!  Thanks for all the wonderfull comments.  I really enjoyed working on this shot.', '2002-11-11 10:12:00.000000', NULL, 0),
