(150854, 7812, 888, '<td valign="top">Its the wooden woodpecker show- nice spin on the "touch wood" myth</td>', 'Its the wooden woodpecker show- nice spin on the "touch wood" myth', '2002-11-04 06:10:00.000000', NULL, 1),
(150855, 7812, 4536, '<td valign="top">funny.<br/>bird looks fake.<br/>also seems to have an overall yellow cast to it, was this intentional?<br/>nice framing.</td>', 'funny.bird looks fake.also seems to have an overall yellow cast to it, was this intentional?nice framing.', '2002-11-04 11:38:00.000000', NULL, 1),
