(150972, 7819, 811, '<td valign="top">Great focus and lighting, and I really like the composition here.  karmat</td>', 'Great focus and lighting, and I really like the composition here.  karmat', '2002-11-06 14:11:00.000000', NULL, 1),
(150973, 7819, 2706, '<td valign="top">simple, yet powerful. The glare of light off the penny along with the dark background makes the picture. Also, good idea to have the penny standing upright instead of laying flat - that adds a little twist to it and makes the picture more interesting.</td>', 'simple, yet powerful. The glare of light off the penny along with the dark background makes the picture. Also, good idea to have the penny standing upright instead of laying flat - that adds a little twist to it and makes the picture more interesting.', '2002-11-06 21:19:00.000000', NULL, 1),
(150974, 7819, 5106, '<td valign="top">Very nicely done. The blurred reflection on the wood floor is a nice effect for composition.</td>', 'Very nicely done. The blurred reflection on the wood floor is a nice effect for composition.', '2002-11-08 22:35:00.000000', NULL, 1),
(150975, 7819, 2567, '<td valign="top">Nice shot</td>', 'Nice shot', '2002-11-08 22:47:00.000000', NULL, 1),
(150976, 7819, 4648, '<td valign="top">Not quite a 10 but a good strong 9.  Like the way the light brings out the writing and shows the way from the left side of the shot to spotlight the penny.  Good corpping.</td>', 'Not quite a 10 but a good strong 9.  Like the way the light brings out the writing and shows the way from the left side of the shot to spotlight the penny.  Good corpping.', '2002-11-09 22:28:00.000000', NULL, 1),
(150977, 7819, 3540, '<td valign="top">Good lighting.  Well taken photo.  Good use of negative space as well - Inspzil</td>', 'Good lighting.  Well taken photo.  Good use of negative space as well - Inspzil', '2002-11-10 08:18:00.000000', NULL, 1),
(150978, 7819, 2553, '<td valign="top">Well done.   Your lighting really makes the shot for me.  lhall</td>', 'Well done.   Your lighting really makes the shot for me.  lhall', '2002-11-10 21:23:00.000000', NULL, 1),
(150979, 7819, 1143, '<td valign="top">High quality shot. Really cool lighting. I like the slant - it creates an illusion all on its own b/c the penny isn''t rolling  ;oP   Nice reflection. What would u think of putting a shoe in the pic?  Just a thought.  ~indi</td>', 'High quality shot. Really cool lighting. I like the slant - it creates an illusion all on its own b/c the penny isn''t rolling  ;oP   Nice reflection. What would u think of putting a shoe in the pic?  Just a thought.  ~indi', '2002-11-10 23:42:00.000000', NULL, 1),
(150980, 7819, 2792, '<td valign="top">Congrats Kollin!  Awesome shot!  =-)</td>', 'Congrats Kollin!  Awesome shot!  =-)', '2002-11-11 12:15:00.000000', NULL, 0),
(150981, 7820, 2792, '<td valign="top">The title sure makes it sound like a supersition.  Love to have a link so I can read about it.  Nice photo overall.  9/10!  erin_m02</td>', 'The title sure makes it sound like a supersition.  Love to have a link so I can read about it.  Nice photo overall.  9/10!  erin_m02', '2002-11-04 13:13:00.000000', NULL, 1),
