INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(151026, 7823, 3280, '<td valign="top">Is it really black or just a silohuette?  The thing in the middle is very distracting.  I like the rest.  DPz</td>', 'Is it really black or just a silohuette?  The thing in the middle is very distracting.  I like the rest.  DPz', '2002-11-04 20:50:00.000000', NULL, 1),
(151027, 7823, 1041, '<td valign="top">challenge -- met<br/>technical -- while i like high-key shots, i personally feel that it doesn''t work so well here.  i''m searching for the cat''s eye, and the foreground just seems to blend into the white.<br/>composition -- like the position of the cat and the fact that its reflection is there, too.  whatever that black thing to the left of the cat is, is very distracting to me.<br/>-- gr8photos.</td>', 'challenge -- mettechnical -- while i like high-key shots, i personally feel that it doesn''t work so well here.  i''m searching for the cat''s eye, and the foreground just seems to blend into the white.composition -- like the position of the cat and the fact that its reflection is there, too.  whatever that black thing to the left of the cat is, is very distracting to me.-- gr8photos.', '2002-11-07 14:51:00.000000', NULL, 1),
(151028, 7823, 2488, '<td valign="top">Artistic!!</td>', 'Artistic!!', '2002-11-08 08:21:00.000000', NULL, 1),
(151029, 7823, 3018, '<td valign="top">I like the contrasts in this picture.  The cat being all black and the washed out background are great.  I would''ve prefer a pure black &amp; white image.</td>', 'I like the contrasts in this picture.  The cat being all black and the washed out background are great.  I would''ve prefer a pure black & white image.', '2002-11-08 17:13:00.000000', NULL, 1),
(151030, 7823, 4648, '<td valign="top">Too much empty space.  Is that cat on a car?  What is that in front of the car(?)?  Is that a katsup squirt bottle.  Bad surface cat is standing on.  Can''t possible give more than 3 even though it is in focus.</td>', 'Too much empty space.  Is that cat on a car?  What is that in front of the car(?)?  Is that a katsup squirt bottle.  Bad surface cat is standing on.  Can''t possible give more than 3 even though it is in focus.', '2002-11-08 23:22:00.000000', NULL, 1),
(151031, 7823, 2221, '<td valign="top">Nice photo! I like the high contrast. Just a suggestion: try a vertical format. Cut the photo in two halves and crop out the left part. I think that looks better. That way the negative space is more effective. -stephan</td>', 'Nice photo! I like the high contrast. Just a suggestion: try a vertical format. Cut the photo in two halves and crop out the left part. I think that looks better. That way the negative space is more effective. -stephan', '2002-11-10 09:54:00.000000', NULL, 1),
(151032, 7823, 2011, '<td valign="top">Best one of all the black cat shots this week.</td>', 'Best one of all the black cat shots this week.', '2002-11-10 13:11:00.000000', NULL, 1),
(151033, 7823, 2553, '<td valign="top">Love your shot/post processing - however you did it, I like the way this looks. lhall</td>', 'Love your shot/post processing - however you did it, I like the way this looks. lhall', '2002-11-10 21:18:00.000000', NULL, 1),
(151034, 7823, 4162, '<td valign="top">I love the simplicity of this, the contrast is great. I really like the silhouette of the cat, could be nice to have a hint of the eyes.</td>', 'I love the simplicity of this, the contrast is great. I really like the silhouette of the cat, could be nice to have a hint of the eyes.', '2002-11-10 21:40:00.000000', NULL, 1),
(151035, 7824, 4267, '<td valign="top">pretty funny. that photo should get tons of comments! :o)</td>', 'pretty funny. that photo should get tons of comments! :o)', '2002-11-04 00:36:00.000000', NULL, 1),
(151036, 7824, 4493, '<td valign="top">Cute idea... put the kid at the breakfast table with a cup of coffee and a grapefruit and I think the concept would have been pulled even better. Good DOF and lighting.</td>', 'Cute idea... put the kid at the breakfast table with a cup of coffee and a grapefruit and I think the concept would have been pulled even better. Good DOF and lighting.', '2002-11-04 09:59:00.000000', NULL, 1),
